class TimeMap {
    struct Data {
        vector<int> times;
        vector<string> vals;
    };
    unordered_map<string, Data> mp;
public:
    TimeMap() = default;

    void set(string key, string value, int timestamp) {
        Data &d = mp[key];
        d.times.push_back(timestamp);
        d.vals.push_back(move(value));
    }

    string get(string key, int timestamp) {
        auto it = mp.find(key);
        if (it == mp.end()) return "";
        const Data &d = it->second;
        if (d.times.empty()) return "";
        // upper_bound returns first element > timestamp
        auto ub = upper_bound(d.times.begin(), d.times.end(), timestamp);
        if (ub == d.times.begin()) return "";
        size_t idx = static_cast<size_t>(ub - d.times.begin() - 1);
        return d.vals[idx];
    }
};

